use semio_framework_test_fixtures::fixture_text;
use super::*;
use semio_framework_value::{retained_clone::RetainedCloneSource,retirement::{RetireOwned,controlled::ControlledRetirement}};
fn observe_heap<T>(f:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);(value,(heap.requested_bytes,heap.released_bytes))}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes.max(257),maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn source<T:RetireOwned+Sync+'static>(value:T)->RetainedCloneSource<T>{let d=RetainedCloneSource::<T>::owned_constructor_demand::<()>();RetainedCloneSource::admit_owned(value,(),grant(RetirementDemand{copy_bytes:RetainedCloneSource::<T>::constructor_copy_bytes(),capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()})).map_err(|(e,..)|e).unwrap().0}
fn close_source<T:RetireOwned+Sync+'static>(source:&mut RetainedCloneSource<T>){let mut turns=0;while !source.terminal_is_empty(){let g=grant(source.next_close_demand(4096).unwrap());assert!(source.close_step(g).unwrap().progress().fits(g));assert!({turns+=1;turns}<100000);}}
fn drain<T:RetireOwned>(value:T){let mut close=ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();let mut turns=0;while !close.terminal_is_empty(){let g=grant(close.next_demand(4096).unwrap());assert!(close.step(g).unwrap().progress().fits(g));assert!({turns+=1;turns}<100000);}}
fn nullable(value:&serde_json::Value)->Option<String>{value.as_str().map(str::to_string)}
fn close<T:RetainedEquality+RetainedClone>(p:&mut RetainedFieldChange<T>){p.begin_close();let mut turns=0;while !p.terminal_is_empty(){let d=p.close_demand(4096).unwrap();let g=grant(d);assert_eq!(p.close_step(RetainedCloneGrant{maximum_items:0,..g}).unwrap().progress(),Default::default());if d.release_bytes>0{assert_eq!(p.close_step(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g}).unwrap().progress(),Default::default());}assert!(p.close_step(g).unwrap().progress().fits(g));assert!({turns+=1;turns}<100000);}}

#[test]
fn optional_field_sparse_changes_and_inverse_preserve_original_sources(){let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../../🪡️field/🟰️change/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){let mut authored=source(nullable(&row["authored"]));let mut original=source(nullable(&row["original"]));let pointer=original.borrow().get().as_ref().map(|text|text.as_ptr());let(mut field,heap)=observe_heap(RetainedFieldChange::<Option<String>>::default);assert_eq!(heap,(0,0));let mut turns=0;while !field.ready(){let g=grant(field.decision_demand(authored.borrow(),original.borrow(),257).unwrap());assert_eq!(field.decide(authored.borrow(),original.borrow(),257,RetainedCloneGrant{maximum_items:0,..g}).unwrap().progress(),Default::default());assert!(field.decide(authored.borrow(),original.borrow(),257,g).unwrap().progress().fits(g));assert!({turns+=1;turns}<100000);}let g=grant(field.decision_demand(authored.borrow(),original.borrow(),257).unwrap());let(change,p)=field.take_change(g).unwrap().unwrap();assert!(p.fits(g));assert_eq!(change.is_none(),row["unchanged"].as_bool().unwrap());if let Some(change)=change.as_ref(){assert_eq!(change,&nullable(&row["change"]));}while !field.inverse_ready(){let g=grant(field.inverse_demand(original.borrow(),257).unwrap());assert!(field.inverse(original.borrow(),257,g).unwrap().progress().fits(g));assert!({turns+=1;turns}<100000);}let g=grant(field.inverse_take_demand().unwrap());let(inverse,p)=field.take_inverse(g).unwrap().unwrap();assert!(p.fits(g));assert_eq!(inverse,nullable(&row["inverse"]));close(&mut field);assert_eq!(original.borrow().get().as_ref().map(|text|text.as_ptr()),pointer);assert_eq!(observe_heap(||drop(field)).1,(0,0));drain(change);drain(inverse);close_source(&mut authored);close_source(&mut original);}}

#[test]
fn optional_field_partial_cancellation_and_foreign_sources_remain_owned(){let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../../🪡️field/🟰️change/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){for cut in fixture["cancelCuts"].as_array().unwrap().iter().map(|cut|cut.as_u64().unwrap()as usize){let mut a=source(nullable(&row["authored"]));let mut b=source(nullable(&row["original"]));let mut foreign=source(nullable(&row["authored"]));let pointer=b.borrow().get().as_ref().map(|text|text.as_ptr());let mut p=RetainedFieldChange::<Option<String>>::default();let mut turns=0;while !p.ready()&&turns<cut{let g=grant(p.decision_demand(a.borrow(),b.borrow(),257).unwrap());assert!(p.decide(a.borrow(),b.borrow(),257,g).unwrap().progress().fits(g));turns+=1;}if turns>0{assert!(p.equality.verify(foreign.borrow(),b.borrow()).is_err());}let mut change=None;let mut inverse=None;if p.ready()&&turns<cut{let g=grant(p.decision_demand(a.borrow(),b.borrow(),257).unwrap());change=Some(p.take_change(g).unwrap().unwrap().0);turns+=1;while !p.inverse_ready()&&turns<cut{let g=grant(p.inverse_demand(b.borrow(),257).unwrap());assert!(p.inverse(b.borrow(),257,g).unwrap().progress().fits(g));turns+=1;}if p.inverse_ready()&&turns<cut{inverse=Some(p.take_inverse(grant(p.inverse_take_demand().unwrap())).unwrap().unwrap().0);}}close(&mut p);assert_eq!(b.borrow().get().as_ref().map(|text|text.as_ptr()),pointer);drain(change);drain(inverse);close_source(&mut a);close_source(&mut b);close_source(&mut foreign);}}
 assert_optional_original_byte_pairs();
 for(left,right,equal)in[(0.0f64,-0.0f64,true),(f64::NAN,f64::NAN,false),(1.0,2.0,false)]{let mut l=source(Some(left));let mut r=source(Some(right));let mut compare=RetainedEqualityOwner::<Option<f64>>::new();while compare.result().is_none(){let g=grant(compare.demand(l.borrow(),r.borrow(),257).unwrap());assert!(compare.advance(l.borrow(),r.borrow(),g).unwrap().progress.fits(g));}assert_eq!(compare.result(),Some(equal));compare.begin_close();while !compare.terminal_is_empty(){let g=grant(compare.close_demand(4096).unwrap());assert!(compare.close_step(g).unwrap().progress().fits(g));}close_source(&mut l);close_source(&mut r);}}

fn assert_optional_original_byte_pairs(){
 for(left,right,equal)in[([vec![1u8,2],vec![3,4]],[vec![1u8,2],vec![3,4]],true),([vec![1u8,2],vec![3,4]],[vec![1u8,2],vec![3,5]],false),([vec![1u8,2],vec![3,4]],[vec![1u8],vec![3,4]],false)]{
 let mut l=source(Some(left));let mut r=source(Some(right));let mut c=RetainedEqualityOwner::<Option<[Vec<u8>;2]>>::new();
 while c.result().is_none(){let g=grant(c.demand(l.borrow(),r.borrow(),257).unwrap());assert_eq!(c.advance(l.borrow(),r.borrow(),RetainedCloneGrant{maximum_items:0,..g}).unwrap().progress,Default::default());assert!(c.advance(l.borrow(),r.borrow(),g).unwrap().progress.fits(g));}
 assert_eq!(c.result(),Some(equal));c.begin_close();while !c.terminal_is_empty(){let g=grant(c.close_demand(4096).unwrap());assert!(c.close_step(g).unwrap().progress().fits(g));}close_source(&mut l);close_source(&mut r);
 }
}

fn exercise_plain<T:RetainedEquality+RetainedClone+Clone>(authored:T,original:T,unchanged:bool,cut:Option<usize>,equivalent:impl Fn(&T,&T)->bool){let expected_change=authored.clone();let expected_inverse=original.clone();let mut a=source(authored);let mut b=source(original);let mut foreign=source(expected_change.clone());let(mut p,heap)=observe_heap(RetainedFieldChange::<T>::default);assert_eq!(heap,(0,0));let mut turns=0;while !p.ready()&&cut.is_none_or(|cut|turns<cut){let g=grant(p.decision_demand(a.borrow(),b.borrow(),257).unwrap());assert_eq!(p.decide(a.borrow(),b.borrow(),257,RetainedCloneGrant{maximum_copy_bytes:0,..g}).unwrap().progress(),Default::default());assert!(p.decide(a.borrow(),b.borrow(),257,g).unwrap().progress().fits(g));turns+=1;assert!(turns<100000);}if turns>0{assert!(p.equality.verify(foreign.borrow(),b.borrow()).is_err());}let mut change=None;let mut inverse=None;if p.ready()&&cut.is_none_or(|cut|turns<cut){let g=grant(p.change_demand().unwrap());let(value,receipt)=p.take_change(g).unwrap().unwrap();assert!(receipt.fits(g));assert_eq!(value.is_none(),unchanged);if let Some(value)=value.as_ref(){assert!(equivalent(value,&expected_change));}change=Some(value);turns+=1;while !p.inverse_ready()&&cut.is_none_or(|cut|turns<cut){let g=grant(p.inverse_demand(b.borrow(),257).unwrap());assert!(p.inverse(b.borrow(),257,g).unwrap().progress().fits(g));turns+=1;assert!(turns<100000);}if p.inverse_ready()&&cut.is_none_or(|cut|turns<cut){let g=grant(p.inverse_take_demand().unwrap());let(value,receipt)=p.take_inverse(g).unwrap().unwrap();assert!(receipt.fits(g));assert!(equivalent(&value,&expected_inverse));inverse=Some(value);}}close(&mut p);assert_eq!(observe_heap(||drop(p)).1,(0,0));drain(change);drain(inverse);drain(expected_change);drain(expected_inverse);close_source(&mut a);close_source(&mut b);close_source(&mut foreign);}
#[test]
fn typed_field_changes_plain_text_bytes_and_ieee_preserve_original_children(){let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../../🪡️field/🟰️change/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in fixture["plainCases"].as_array().unwrap(){for cut in fixture["cancelCuts"].as_array().unwrap().iter().map(|cut|Some(cut.as_u64().unwrap()as usize)).chain(std::iter::once(None)){let same=row["unchanged"].as_bool().unwrap();match row["type"].as_str().unwrap(){"text"=>exercise_plain(row["authored"].as_str().unwrap().to_owned(),row["original"].as_str().unwrap().to_owned(),same,cut,|a,b|a==b),"bytes"=>{let bytes=|v:&serde_json::Value|v.as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect::<Vec<_>>();exercise_plain(bytes(&row["authored"]),bytes(&row["original"]),same,cut,|a,b|a==b)},"f64"=>{let number=|v:&serde_json::Value|if v=="nan"{f64::NAN}else{v.as_str().unwrap().parse::<f64>().unwrap()};exercise_plain(number(&row["authored"]),number(&row["original"]),same,cut,|a,b|a.to_bits()==b.to_bits());},_=>unreachable!()}}}}
